// Package persistence implements the domain
// interfaces with queries generated by sqlc. The generated code lives in
// package sqlcgen; edit queries.sql and regenerate it instead of editing it.
package persistence

import (
	"context"
	"fmt"

	"example.com/shop/internal/adapters/persistence/sqlcgen"
	"example.com/shop/internal/domain"
)

// itemStore is a domain.ItemStore backed by sqlc queries.
type itemStore struct {
	q *sqlcgen.Queries
}

// New returns a domain.ItemStore that stores items in db.
func New(db sqlcgen.DBTX) domain.ItemStore {
	return &itemStore{q: sqlcgen.New(db)}
}

func (s *itemStore) List(ctx context.Context) ([]domain.Item, error) {
	rows, err := s.q.ListItems(ctx)
	if err != nil {
		return nil, fmt.Errorf("list items: %w", err)
	}
	list := make([]domain.Item, len(rows))
	for i, row := range rows {
		list[i] = toModel(row)
	}
	return list, nil
}

func (s *itemStore) Create(ctx context.Context, name string) (domain.Item, error) {
	row, err := s.q.CreateItem(ctx, name)
	if err != nil {
		return domain.Item{}, fmt.Errorf("create item: %w", err)
	}
	return toModel(row), nil
}

func toModel(row sqlcgen.Item) domain.Item {
	return domain.Item{ID: row.ID, Name: row.Name, CreatedAt: row.CreatedAt}
}
